export class PlanEstudio {
  codigo;
  anioVigencia;
  materias;
  constructor(codigo, anioVigencia, materias) {
    this.codigo = codigo;
    this.anioVigencia = anioVigencia;
    this.materias = materias;
  }
  getCodigo() {
    return this.codigo;
  }
  getAnioVigencia() {
    return this.anioVigencia;
  }
  getMaterias() {
    return this.materias;
  }
  getCorrelativasDe(materia) {
    return materia.getCorrelativas();
  }
}
